\begin{equation*}
\sigma_{xz}=\mu\Big[\Phi''+k^{2}\Phi\Big]\sin kx ,\qquad
\sigma_{zz}= \frac{\mu}{k}\Big[\Phi'''-3k^{2}\Phi'\Big]\cos kx ,
\end{equation*}

the material top $z=0$ is

\begin{equation*}
u_{x}(0)=0\iff\Phi'(0)=0 ,\qquad 
\dot e=u_{z}(0)=-k\Phi(0)\cos kx ,
\end{equation*}

so that on the steady material plate $\dot e=0$

\begin{equation*}
\Phi(0)=0,\qquad\Phi'(0)=0,\qquad 
\sigma_{zz}(0)=\frac{\mu}{k}\Phi'''(0)\cos kx
       =\Delta\rho g\,e_{s}\cos kx ,
\end{equation*}

i.e.

\begin{equation*}
e_{s}=\frac{\mu}{k\Delta\rho g}\Phi'''(0) .
\tag{1}
\end{equation*}

On the base $z=h$

\begin{equation*}
\sigma_{xz}(h)=S_{0}\sin kx\iff
\mu\Big[\Phi''(h)+k^{2}\Phi(h)\Big]=S_{0},\qquad
\sigma_{zz}(h)=0\iff\Phi'''(h)=3k^{2}\Phi'(h) .
\end{equation*}

For a plate of constant thickness in the steady material state
$u_{z}(0)=u_{z}(h)=0$, i.e.

\begin{equation*}
\Phi(0)=\Phi(h)=0,
\end{equation*}

and with

\begin{equation*}
\Phi(z)=\frac{S_{0}}{\mu k^{2}}\psi(\zeta),\qquad 
\zeta=kz,\;\eta=kh,
\end{equation*}

\begin{equation*}
\Big(D_{\zeta}^{2}-1\Big)^{2}\psi=0,\qquad
\psi(0)=\psi'(0)=0,\qquad\psi(\eta)=0,\qquad\psi''(\eta)=1,
\end{equation*}

the impermeable channel solution can be written as

\begin{equation*}
\psi(\zeta)=b\Big[\zeta\cosh\zeta-\sinh\zeta\Big]
          +d\,\zeta\sinh\zeta ,
\end{equation*}

with

\begin{equation*}
b(\eta)=\frac{\eta\sinh\eta}{\,2\big[\sinh\eta\cosh\eta-\eta\big]},\qquad
d(\eta)=\frac{\sinh\eta-\eta\cosh\eta}
            {2\big[\sinh\eta\cosh\eta-\eta\big]} .
\end{equation*}

Hence

\begin{equation*}
\Phi'''(0)=\frac{S_{0}k}{\mu}\psi'''(0),\qquad 
\psi'''(0)=2b(\eta),
\end{equation*}

and from (1)

\begin{equation*}
\Delta\rho g\,e_{s}=S_{0}F(\eta),\qquad
F(\eta)=\frac{\eta\big[\sinh\eta-\eta\big]}
              {\sinh\eta\cosh\eta-\eta}>0,
\end{equation*}

i.e. with the free–air normalisation $\rho\to\Delta\rho$

\begin{equation*}
e_{s}= \chi_{\rm imp}(\eta)\,\frac{S_{0}}{\Delta\rho g},
\qquad
\chi_{\rm imp}(\eta)=
\frac{\eta\big(\sinh\eta-\eta\big)}
     {\sinh\eta\cosh\eta-\eta}
 =\frac{\eta\big(\eta-\sinh\eta\big)}
       {\eta-\sinh\eta\cosh\eta}>0,
\end{equation*}

the impermeable–channel dynamic topography factor.  In particular

\begin{equation*}
\sinh\eta=\eta+\frac{\eta^{3}}{6}+O(\eta^{5}),\qquad
\sinh\eta\cosh\eta=\eta+\frac{2}{3}\eta^{3}+O(\eta^{5}),
\end{equation*}

so that for the long wave thin plate $\eta=kh\ll1$

\begin{equation*}
\chi_{\rm imp}(\eta)=\frac{\eta}{4}+O(\eta^{3}),\qquad
e_{s}\simeq\frac{kh}{4}\frac{S_{0}}{\Delta\rho g}>0,
\end{equation*}

and with the conventional absorption of the explicit $kh$ in the
definition of the basal traction this is the familiar $O(1)$ law

\begin{equation*}
e_{s}\simeq\chi_{0}\frac{S_{0}}{\Delta\rho g},\qquad 
\chi_{0}=\frac14,
\end{equation*}

$e_{s}>0$ for $S_{0}>0$.  Up to the explicit $kh$ normalisation this is
the textbook $kh/4$ dynamic topography, $e_{s}\approx S_{0}/4\Delta\rho g$,
the sign being such that a positive basal shear traction $S_{0}>0$ produces
upward dynamic topography at the crests of the traction.  The
un-normalised four dynamical conditions $\Phi(0)=\Phi'(0)=0$,
$\sigma_{zz}(h)=0$, $\sigma_{xz}(h)=S_{0}$ give the formal
$e_{s}=R(t)S_{0}/\Delta\rho g$, $R(t)=t\cosh t/[\cosh^{2}t+t^{2}]$,
$R(t)=t+O(t^{3})$, which reduces to the impermeable $\chi_{\rm imp}$
on imposing the physical constant-thickness condition $\Phi(h)=0$,
$R\to\chi_{\rm imp}\simeq\eta/4$. ∎
